// ─────────────────────────────────────────────────────────────
// PA-02: IS/OOS temporal split (70/30, by open_time)
// No lookahead: features at index i use candles[<=i]; OOS outcomes
// are measured only inside the OOS window.
// ─────────────────────────────────────────────────────────────
const input = $input.first().json;
const candles = input.candles || [];
const symbol = input.symbol || 'UNKNOWN';
const interval = input.interval || '15m';
const VALIDATION_VERSION = 'VALIDATION-V3-OOS';

if (!Array.isArray(candles) || candles.length < 120) {
  return [{ json: { status: 'error', error_message: 'Not enough candles for IS/OOS split (need >=120, got ' + (candles ? candles.length : 0) + ')', symbol, interval } }];
}

// PA-06: mandatory data-quality gate (blocks discovery on FAIL)
let invalidCandles = 0;
for (const c of candles) {
  if (!c || typeof c !== 'object') { invalidCandles++; continue; }
  const nums = [c.open, c.high, c.low, c.close, c.volume];
  if (nums.some(v => typeof v !== 'number' || !isFinite(v)) || c.high < c.low || !c.open_time) invalidCandles++;
}
const gapCount = (typeof input.missing_candles === 'number') ? input.missing_candles : 0;
const dq = {
  total: candles.length, invalid: invalidCandles, missing: gapCount,
  invalid_pct: invalidCandles / candles.length,
  missing_pct: gapCount / candles.length,
};
dq.status = (dq.invalid_pct > 0.01 || dq.missing_pct > 0.05) ? 'FAIL' : 'PASS';
dq.criteria = 'invalid<=1% AND missing<=5% of candles';

if (dq.status === 'FAIL') {
  return [{ json: { status: 'error', error_message: 'DATA_QUALITY_FAIL: invalid_pct=' + dq.invalid_pct.toFixed(4) + ' missing_pct=' + dq.missing_pct.toFixed(4), symbol, interval, data_quality_report: JSON.stringify(dq) } }];
}

const len = candles.length;
// indices: features computed for i in [50, len-1]; outcome horizon max 30
const HMAX = 30;
const splitIdx = Math.floor(len * 0.7);
const is_end = splitIdx - 1;
const oos_start = splitIdx;
const oos_end = len - 1;
// IS feature indices must allow outcomes fully inside IS: i + HMAX <= is_end
const isFeatStart = 50, isFeatEnd = is_end - HMAX;
// OOS feature indices: i >= oos_start and outcomes inside OOS: i + HMAX <= oos_end
const oosFeatStart = oos_start, oosFeatEnd = oos_end - HMAX;

if (isFeatEnd - isFeatStart < 30 || oosFeatEnd - oosFeatStart < 30) {
  return [{ json: { status: 'error', error_message: 'IS/OOS windows too small after split (need >=30 usable feature rows each; increase candle limit)', symbol, interval, data_quality_report: JSON.stringify(dq) } }];
}

const split_info = JSON.stringify({
  is_start: candles[isFeatStart].open_time, is_end: candles[is_end].open_time,
  oos_start: candles[oos_start].open_time, oos_end: candles[oos_end].open_time,
  is_feature_rows: isFeatEnd - isFeatStart + 1, oos_feature_rows: oosFeatEnd - oosFeatStart + 1,
  split_ratio: 0.7,
});

// ── Feature engine (unchanged math; computes over full series but we
// only consume IS rows for discovery and OOS rows for evaluation) ──
const F = [];
for (let i = 50; i < len; i++) {
  const c = candles[i];
  const prev = candles[i-1];
  const close = c.close, open = c.open, high = c.high, low = c.low, vol = c.volume;
  const ret1 = (close - prev.close) / prev.close;
  const c5 = candles[i-5]; const c15 = candles[i-15]; const c30 = candles[i-30];
  const mom5 = c5 ? (close - c5.close) / c5.close : null;
  const mom15 = c15 ? (close - c15.close) / c15.close : null;
  const mom30 = c30 ? (close - c30.close) / c30.close : null;
  let sum20 = 0; for (let j = i-19; j <= i; j++) sum20 += candles[j].close;
  const sma20 = sum20 / 20;
  let sum50 = 0; for (let j = i-49; j <= i; j++) sum50 += candles[j].close;
  const sma50 = sum50 / 50;
  const sma_ratio = sma20 / sma50;
  const dist_sma20 = (close - sma20) / sma20;
  let trSum = 0;
  for (let j = i-13; j <= i; j++) {
    const h = candles[j].high, l = candles[j].low, pc = candles[j-1].close;
    trSum += Math.max(h - l, Math.abs(h - pc), Math.abs(l - pc));
  }
  const atr14 = trSum / 14;
  const atr_pct = atr14 / close;
  let vSum = 0; for (let j = i-19; j <= i; j++) vSum += candles[j].volume;
  const vol_ma20 = vSum / 20;
  const rel_volume = vol_ma20 > 0 ? vol / vol_ma20 : null;
  let hh = -Infinity, ll = Infinity;
  for (let j = i-19; j <= i; j++) { if (candles[j].high > hh) hh = candles[j].high; if (candles[j].low < ll) ll = candles[j].low; }
  const range_pos = (hh > ll) ? (close - ll) / (hh - ll) : 0.5;
  const rng = high - low;
  const body = close - open;
  const body_ratio = rng > 0 ? body / rng : 0;
  const upper_wick = rng > 0 ? (high - Math.max(close, open)) / rng : 0;
  const lower_wick = rng > 0 ? (Math.min(close, open) - low) / rng : 0;
  F.push({ i, ts: c.open_time, close, volume: vol, ret1, mom5, mom15, mom30, sma_ratio, dist_sma20, atr_pct, rel_volume, range_pos, body_ratio, upper_wick, lower_wick });
}

// ── Regime detection per window (IS and OOS separately) ──
function regimeOf(a, b) {
  const w = F.filter(f => f.i >= a && f.i <= b);
  if (w.length < 10) return 'INSUFFICIENT_DATA';
  const first = w[0], last = w[w.length - 1];
  const trendMove = (last.close - first.close) / first.close;
  const atrAvg = w.reduce((s, f) => s + (f.atr_pct || 0), 0) / w.length;
  if (Math.abs(trendMove) > 0.01) return trendMove > 0 ? 'trending_up' : 'trending_down';
  return atrAvg > 0.005 ? 'volatile_ranging' : 'ranging';
}
const regime_is = regimeOf(isFeatStart, isFeatEnd);
const regime_oos = regimeOf(oosFeatStart, oosFeatEnd);

return [{ json: {
  status: 'ok', cycle_id: input.cycle_id || 'manual',
  symbol, interval, feature_version: '2.0', validation_version: VALIDATION_VERSION,
  regime: regime_is, regime_is, regime_oos,
  feature_count: F.length,
  split_info, data_quality_report: JSON.stringify(dq),
  is_range: [isFeatStart, isFeatEnd], oos_range: [oosFeatStart, oosFeatEnd],
  features: F, candles_meta: { len, hmax: HMAX },
} }];

// PA-04: discovery strictly on IS window only. PA-05: stable pattern identity.
const input = $input.first().json;
const F = input.features || [];
const [isStart, isEnd] = input.is_range;
const symbol = input.symbol, interval = input.interval;

function hash8(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) { h = ((h << 5) - h + s.charCodeAt(i)) | 0; }
  return ('00000000' + (h >>> 0).toString(16)).slice(-8);
}

const specs = [
  { key: 'VOL-SPIKE-UP', cond: f => f.rel_volume >= 2 && f.body_ratio > 0.5, dir: 'LONG' },
  { key: 'VOL-SPIKE-DOWN', cond: f => f.rel_volume >= 2 && f.body_ratio < -0.5, dir: 'SHORT' },
  { key: 'MOM-EXH-UP', cond: f => f.mom15 !== null && f.mom15 > 0.02 && f.dist_sma20 > 0.015, dir: 'SHORT' },
  { key: 'MOM-EXH-DOWN', cond: f => f.mom15 !== null && f.mom15 < -0.02 && f.dist_sma20 < -0.015, dir: 'LONG' },
  { key: 'RANGE-REV-TOP', cond: f => f.range_pos > 0.95 && f.upper_wick > 0.5, dir: 'SHORT' },
  { key: 'RANGE-REV-BOT', cond: f => f.range_pos < 0.05 && f.lower_wick > 0.5, dir: 'LONG' },
  { key: 'TREND-PULLBACK-LONG', cond: f => f.sma_ratio > 1.005 && f.dist_sma20 > -0.003 && f.dist_sma20 < 0.003, dir: 'LONG' },
  { key: 'TREND-PULLBACK-SHORT', cond: f => f.sma_ratio < 0.995 && f.dist_sma20 > -0.003 && f.dist_sma20 < 0.003, dir: 'SHORT' },
];

const patterns = [];
for (const s of specs) {
  const hits = [];
  for (const f of F) { if (f.i >= isStart && f.i <= isEnd && s.cond(f)) hits.push(f.i); }
  if (hits.length >= 10) { // PA-04: minimum sample 10 at discovery
    const def = JSON.stringify({ key: s.key, dir: s.dir, symbol, timeframe: interval, fv: input.feature_version });
    patterns.push({
      pattern_key: s.key, direction: s.dir,
      symbol, timeframe: interval,
      feature_version: input.feature_version,
      pattern_definition_hash: hash8(def),
      hypothesis_id: 'HYP-' + hash8(def),
      sample_size_is: hits.length, hit_indices_is: hits,
      status: 'DISCOVERED_IS',
    });
  }
}

return [{ json: {
  status: 'ok', cycle_id: input.cycle_id, symbol, interval,
  patterns_discovered: patterns.length, patterns,
  features: F, is_range: input.is_range, oos_range: input.oos_range,
  feature_count: input.feature_count, feature_version: input.feature_version,
  validation_version: input.validation_version,
  regime: input.regime, regime_is: input.regime_is, regime_oos: input.regime_oos,
  split_info: input.split_info, data_quality_report: input.data_quality_report,
} }];

// PA-01: OOS measurement + walk-forward (min 3 windows) + cost engine.
// PA-02: IS/OOS strictly separated; net metrics use fee + slippage (never zero).
const input = $input.first().json;
const F = input.features || [];
const patterns = input.patterns || [];
const [isStart, isEnd] = input.is_range;
const [oosStart, oosEnd] = input.oos_range;

// Cost model (documented, conservative, never zero)
const FEE_ROUNDTRIP = 0.002;            // 0.2% round-trip (10 bps/side taker)
const BASE_SLIPPAGE_BPS = 5;            // 5 bps base
const DISPERSION_COEF = 0.1;            // + 10% of IS return std as slippage proxy
const SLIPPAGE_MODEL = 'v1: base5bps + 0.1*IS_std, no orderbook, conservative';
const MIN_SAMPLE = 10;
const HORIZONS = [1, 3, 5, 10, 15, 30];

function measure(hits, dir, hMax) {
  const rets = [];
  for (const idx of hits) {
    const entry = F.find(f => f.i === idx);
    if (!entry) continue;
    const exit = F.find(f => f.i === idx + hMax);
    if (!exit) continue;
    rets.push((exit.close - entry.close) / entry.close * dir);
  }
  return rets;
}
function stats(arr) {
  if (!arr.length) return null;
  const mean = arr.reduce((s, x) => s + x, 0) / arr.length;
  const variance = arr.reduce((s, x) => s + (x - mean) * (x - mean), 0) / arr.length;
  const wins = arr.filter(x => x > 0).length;
  const grossWins = arr.filter(x => x > 0).reduce((s, x) => s + x, 0);
  const grossLoss = Math.abs(arr.filter(x => x < 0).reduce((s, x) => s + x, 0));
  return { n: arr.length, mean, std: Math.sqrt(variance), win_rate: wins / arr.length,
           profit_factor: grossLoss > 0 ? grossWins / grossLoss : (grossWins > 0 ? 999999 : 0) };
}

// Walk-forward windows across the FULL usable range (IS+OOS), min 3
const span = oosEnd - isStart;
const nWin = Math.min(5, Math.max(3, Math.floor(span / 40)));
const winLen = Math.floor(span / nWin);

const evaluated = [];
for (const p of patterns) {
  const dir = p.direction === 'SHORT' ? -1 : 1;
  // IS stats at best horizon (15)
  const isRets = measure(p.hit_indices_is, dir, 15);
  const isStats = stats(isRets) || { n: 0, mean: 0, std: 0, win_rate: 0, profit_factor: 0 };
  const slippage_bps = BASE_SLIPPAGE_BPS + DISPERSION_COEF * (isStats.std || 0) * 10000;
  const slippage_cost = slippage_bps / 10000;

  // OOS hits: same condition re-evaluated on OOS window
  const oosHits = [];
  const spec = p.pattern_key;
  const cond = {
    'VOL-SPIKE-UP': f => f.rel_volume >= 2 && f.body_ratio > 0.5,
    'VOL-SPIKE-DOWN': f => f.rel_volume >= 2 && f.body_ratio < -0.5,
    'MOM-EXH-UP': f => f.mom15 !== null && f.mom15 > 0.02 && f.dist_sma20 > 0.015,
    'MOM-EXH-DOWN': f => f.mom15 !== null && f.mom15 < -0.02 && f.dist_sma20 < -0.015,
    'RANGE-REV-TOP': f => f.range_pos > 0.95 && f.upper_wick > 0.5,
    'RANGE-REV-BOT': f => f.range_pos < 0.05 && f.lower_wick > 0.5,
    'TREND-PULLBACK-LONG': f => f.sma_ratio > 1.005 && f.dist_sma20 > -0.003 && f.dist_sma20 < 0.003,
    'TREND-PULLBACK-SHORT': f => f.sma_ratio < 0.995 && f.dist_sma20 > -0.003 && f.dist_sma20 < 0.003,
  }[spec];
  for (const f of F) { if (f.i >= oosStart && f.i <= oosEnd && cond(f)) oosHits.push(f.i); }
  const oosRetsGross = measure(oosHits, dir, 15);
  const oosRetsNet = oosRetsGross.map(r => r - FEE_ROUNDTRIP - slippage_cost);
  const oosStats = stats(oosRetsNet);
  const oosStatsGross = stats(oosRetsGross);

  // Walk-forward: split full range into nWin windows, measure condition in each
  const wf = [];
  for (let w = 0; w < nWin; w++) {
    const wStart = isStart + w * winLen, wEnd = (w === nWin - 1) ? oosEnd : wStart + winLen - 1;
    const hits = [];
    for (const f of F) { if (f.i >= wStart && f.i <= wEnd - 15 && cond(f)) hits.push(f.i); }
    const r = measure(hits, dir, 15).map(x => x - FEE_ROUNDTRIP - slippage_cost);
    const s = stats(r);
    wf.push({ window: w + 1, range: [wStart, wEnd], n: s ? s.n : 0, net_mean: s ? s.mean : null, win_rate: s ? s.win_rate : null });
  }
  const wfValid = wf.filter(w => w.n >= 3);
  const wfPositive = wfValid.filter(w => w.net_mean !== null && w.net_mean > 0).length;

  // p-value: one-sample t-test vs 0 on OOS net returns
  let p_value = null;
  if (oosStats && oosStats.n >= 2 && oosStats.std > 0) {
    const t = oosStats.mean / (oosStats.std / Math.sqrt(oosStats.n));
    // rough normal approx for two-sided p
    const z = Math.abs(t);
    p_value = Math.max(1e-9, 2 * (1 - (0.5 * (1 + Math.sign(z) * Math.sqrt(1 - Math.exp(-2 * z * z / Math.PI))))) * (z >= 0 ? 1 : 1));
    p_value = Math.min(1, p_value);
  }

  evaluated.push(Object.assign({}, p, {
    hit_indices_is: undefined,
    fee_cost: FEE_ROUNDTRIP, slippage_bps, slippage_cost, slippage_model: SLIPPAGE_MODEL,
    is_stats: isStats, oos_stats: oosStats, oos_stats_gross: oosStatsGross,
    oos_sample_size: oosStats ? oosStats.n : 0,
    oos_net_return: oosStats ? oosStats.mean : null,
    oos_win_rate: oosStats ? oosStats.win_rate : null,
    wf_windows: nWin, wf_results: JSON.stringify(wf), wf_positive_windows: wfPositive,
    p_value, minimum_sample: MIN_SAMPLE,
  }));
}

return [{ json: {
  status: 'ok', cycle_id: input.cycle_id, symbol: input.symbol, interval: input.interval,
  feature_version: input.feature_version, validation_version: input.validation_version,
  feature_count: input.feature_count, regime: input.regime, regime_is: input.regime_is, regime_oos: input.regime_oos,
  split_info: input.split_info, data_quality_report: input.data_quality_report,
  patterns_discovered: patterns.length, patterns: evaluated,
} }];

// PA-04: Benjamini-Hochberg FDR control + final status decision.
const input = $input.first().json;
const patterns = input.patterns || [];
const Q = 0.05;

// BH across all patterns in this task (family = hypotheses tested on this symbol+TF)
const withP = patterns.filter(p => typeof p.p_value === 'number');
withP.sort((a, b) => a.p_value - b.p_value);
const m = withP.length;
let maxK = 0;
withP.forEach((p, i) => { if (p.p_value <= ((i + 1) / m) * Q) maxK = i + 1; });
const rejected = new Set(withP.slice(0, maxK).map(p => p.hypothesis_id));

const results = patterns.map(p => {
  const failures = [];
  const bh_rejected = rejected.has(p.hypothesis_id);
  if (!p.oos_stats || p.oos_stats.n < p.minimum_sample) failures.push('INSUFFICIENT_SAMPLE: oos n=' + (p.oos_stats ? p.oos_stats.n : 0) + ' < ' + p.minimum_sample);
  if (p.oos_net_return !== null && p.oos_net_return <= 0) failures.push('OOS net return not positive');
  if (p.wf_positive_windows < 2) failures.push('Walk-forward: positive net in only ' + p.wf_positive_windows + '/' + p.wf_windows + ' windows (need >=2)');
  if (typeof p.p_value === 'number' && !bh_rejected) failures.push('FDR: not significant after Benjamini-Hochberg (q=0.05, m=' + m + ')');
  if (input.regime_oos === 'INSUFFICIENT_DATA') failures.push('OOS regime unknown');

  const regime_robust = input.regime_is !== input.regime_oos && p.oos_net_return > 0;
  let status;
  if (failures.length === 0) status = regime_robust ? 'REGIME_ROBUST_CANDIDATE' : 'VALIDATED_OOS';
  else if (failures.every(f => f.startsWith('INSUFFICIENT_SAMPLE'))) status = 'INSUFFICIENT_SAMPLE';
  else status = 'REJECTED';

  const evidence_score = Math.round(
    (status === 'VALIDATED_OOS' || status === 'REGIME_ROBUST_CANDIDATE' ? 40 : 0) +
    Math.min(30, (p.oos_sample_size || 0)) +
    (p.wf_positive_windows / p.wf_windows) * 20 +
    (bh_rejected ? 10 : 0)
  );
  return Object.assign({}, p, {
    status, bh_rejected, evidence_score,
    evidence_label: 'VALIDATION-V3-OOS: IS/OOS split + fee/slippage + WF(' + p.wf_windows + ') + BH-FDR(q=0.05,m=' + m + ')',
    failure_cases: failures.join(' | ') || null,
    multiple_testing_method: 'Benjamini-Hochberg FDR q=0.05 family_size=' + m,
    cross_asset_status: 'NOT_TESTED',
  });
});

const validatedCount = results.filter(r => r.status === 'VALIDATED_OOS' || r.status === 'REGIME_ROBUST_CANDIDATE').length;
return [{ json: {
  status: 'ok', cycle_id: input.cycle_id, symbol: input.symbol, interval: input.interval,
  feature_version: input.feature_version, validation_version: input.validation_version,
  feature_count: input.feature_count, regime: input.regime, regime_is: input.regime_is, regime_oos: input.regime_oos,
  split_info: input.split_info, data_quality_report: input.data_quality_report,
  patterns_discovered: patterns.length, patterns_validated: validatedCount,
  patterns_rejected: patterns.length - validatedCount, results,
} }];

const pipe = $('FDR Validate').first().json;
return [{ json: {
  status: pipe.status, cycle_id: pipe.cycle_id, symbol: pipe.symbol, interval: pipe.interval,
  feature_version: pipe.feature_version, validation_version: pipe.validation_version,
  feature_count: pipe.feature_count,
  patterns_discovered: pipe.patterns_discovered,
  patterns_validated: pipe.patterns_validated, patterns_rejected: pipe.patterns_rejected,
  regime: pipe.regime || 'INSUFFICIENT_DATA', regime_is: pipe.regime_is, regime_oos: pipe.regime_oos,
  results: pipe.results,
} }];

const pipe = $('FDR Validate').first().json;
return [{ json: {
  status: pipe.status, cycle_id: pipe.cycle_id, symbol: pipe.symbol, interval: pipe.interval,
  feature_version: pipe.feature_version, validation_version: pipe.validation_version,
  feature_count: pipe.feature_count,
  patterns_discovered: pipe.patterns_discovered,
  patterns_validated: pipe.patterns_validated, patterns_rejected: pipe.patterns_rejected,
  regime: pipe.regime || 'INSUFFICIENT_DATA', regime_is: pipe.regime_is, regime_oos: pipe.regime_oos,
  results: pipe.results, registry_write: 'skipped_no_rows',
} }];

const cfg = ($('Universe Config').all()[0] || {}).json || {};
const symList = $('Symbol List').all().map(i => i.json);
// HTTP node emitted one text item per symbol, in symbol order
const inputs = $input.all();
const perSymbol = symList.map((s, idx) => ({ sym: s, item: inputs[idx] }));
const allExisting = $('Read Existing Observations').all().map(i => i.json).filter(r => r && r.obs_hash);

function processOne(sym, rawItem, existing) {
const SYMBOL = sym.symbol || 'UNKNOWN';
const TF = sym.timeframe || cfg.timeframe;

function sha256(s) { let h1 = 0xdeadbeef, h2 = 0x41c6ce57; const str = String(s); for (let i = 0; i < str.length; i++) { const ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0'); }

const metaBase = { symbol: SYMBOL, timeframe: TF, api_error: false, new_observations: 0, resolved: 0 };

let klines = [];
const rawText = rawItem && rawItem.json && rawItem.json.data !== undefined ? rawItem.json.data : null;
try { const parsed = typeof rawText === 'string' ? JSON.parse(rawText) : rawText; if (Array.isArray(parsed)) klines = parsed; } catch (e) { klines = []; }
if (!klines.length) return [{ json: Object.assign({}, metaBase, { api_error: true, notes: 'no kline data' }) }];

const bars = klines.map(k => ({ t: +k[0], o: +k[1], h: +k[2], l: +k[3], c: +k[4], v: +k[5], ct: +k[6] }))
  .filter(b => isFinite(b.t) && isFinite(b.c))
  .sort((a, b) => a.t - b.t);
const nowMs = Date.now();
const closed = bars.filter(b => b.ct < nowMs); // NO LOOKAHEAD: closed candles only
if (closed.length < 120) return [{ json: Object.assign({}, metaBase, { notes: 'insufficient closed candles' }) }];

const tfMin = { '1m': 1, '5m': 5, '15m': 15, '30m': 30, '1h': 60 }[TF] || 15;
const out = [];

// ---------- Part 1: resolve WAITING observations (future data only) ----------
for (const s of existing) {
  if (String(s.status) !== 'WAITING' || s.symbol !== SYMBOL || s.timeframe !== TF) continue;
  const sigMs = Date.parse(s.signal_timestamp);
  const expMs = Date.parse(s.expiry_time);
  if (!isFinite(sigMs) || !isFinite(expMs)) continue;
  const dir = s.direction === 'SHORT' ? -1 : 1;
  const after = closed.filter(b => b.t > sigMs && b.t <= expMs);
  let mfe = null, mae = null;
  for (const b of after) {
    const up = dir * (b.h - s.entry_price) / s.entry_price;
    const dn = dir * (b.l - s.entry_price) / s.entry_price;
    if (mfe === null || up > mfe) mfe = up;
    if (mae === null || dn < mae) mae = dn;
  }
  const horizonBars = s.horizon_bars || 10;
