  const SLIP = (typeof cand.slippage_cost === 'number' && cand.slippage_cost >= 0) ? cand.slippage_cost : 0.0005;
  const COST = FEE + SLIP;

  // Exact Worker feature engine (Compute Features, feature_version 2.0): features at i use candles[<=i]
