    const sma20 = sum20 / 20;
    let sum50 = 0; for (let j = i - 49; j <= i; j++) sum50 += bars[j].c;
    const sma50 = sum50 / 50;
    const c15 = bars[i - 15];
    const mom15 = c15 ? (c.c - c15.c) / c15.c : null;
    const rng = c.h - c.l;
    const body = c.c - c.o;
