const symIdx = Math.floor(cursor / TIMEFRAMES.length);
const tfIdx = cursor % TIMEFRAMES.length;
const symbol = SYMBOLS[symIdx];
const interval = TIMEFRAMES[tfIdx];
const nextCursor = (cursor + 1) % total;
const cycleId = 'DISC-' + Date.now() + '-' + symbol + '-' + interval;
return [{ json: {
