// Convert Binance klines (array of arrays) to the candle objects the
// Research Cycle Worker expects. Drop the last (still-open) candle.
const task = $('Pick Next Task').first().json;
// HTTP node splits the top-level klines array into one item per element — collect them all.
const raw = $input.all().map(i => i.json);
if (!Array.isArray(raw) || raw.length < 200) {
  return [{ json: { status: 'error', error_message: 'Klines fetch failed or too short (got ' + (Array.isArray(raw) ? raw.length : 'non-array') + ')', cycle_id: task.cycle_id, symbol: task.symbol, interval: task.interval } }];
}
let candles = raw.map(k => ({
