  low: parseFloat(k[3]), close: parseFloat(k[4]), volume: parseFloat(k[5]),
  close_time: k[6],
}));
// drop last candle if still open (close_time in the future)
const nowMs = Date.now();
const closed = candles.filter(c => c.close_time < nowMs);
const dropped = candles.length - closed.length;
candles = closed;
if (candles.length < 200) {
  return [{ json: { status: 'error', error_message: 'Not enough closed candles after filtering (' + candles.length + ')', cycle_id: task.cycle_id, symbol: task.symbol, interval: task.interval } }];
}
// gap detection: expected interval ms vs actual open_time deltas
const TF_MS = { '1m': 60000, '5m': 300000, '15m': 900000, '30m': 1800000, '1h': 3600000 };
const step = TF_MS[task.interval] || 900000;
let missing = 0;
for (let i = 1; i < candles.length; i++) {
  const delta = candles[i].open_time - candles[i - 1].open_time;
  if (delta > step) missing += Math.round(delta / step) - 1;
}
return [{ json: {
  status: 'ok',
  cycle_id: task.cycle_id,
  symbol: task.symbol, interval: task.interval,
  candles_fetched: candles.length, open_candles_dropped: dropped,
  missing_candles: missing,
  candles,
  next_cursor: task.next_cursor,
