}
// PENDING / FAILED / own RUNNING (recover) -> claim with attempt+1
return [{ json: { action: 'CLAIM', benchmark_id: task.benchmark_id, task_id: task.task_id, worker_id: task.worker_id, attempt: prev + 1, prev_attempts: prev, symbol: r.symbol, timeframe: r.timeframe, batch_id: r.batch_id } }];

