// METRICS-V1: closed positions only (no outcome leakage).
// CANDIDATE-V1: multi-factor score — win-rate-only ranking is FORBIDDEN.
const accounts = $('Load Accounts').all().map(i => i.json).filter(a => a && a.account_id);
const positions = $('Load Closed Positions').all().map(i => i.json).filter(p => p && p.position_id && p.status === 'CLOSED');
const nowIso = new Date().toISOString();
const METRIC_VERSION = 'METRICS-V1';
const CANDIDATE_VERSION = 'CANDIDATE-V1';

function metricsFor(acct, trades) {
  trades.sort((a, b) => Date.parse(a.exit_time) - Date.parse(b.exit_time));
  const n = trades.length;
  if (!n) {
    return {
      ledger_id: acct.account_id, agent_type: acct.agent_type, agent_ref: acct.agent_ref,
      trades: 0, wins: 0, losses: 0, win_rate: 0, gross_pnl: 0, net_pnl: 0, roi: 0,
      profit_factor: 0, expectancy: 0, avg_win: 0, avg_loss: 0, max_drawdown: 0,
      sharpe: 0, sortino: 0, avg_holding_min: 0, turnover: 0,
      total_fees: 0, total_slippage: 0, total_funding: 0,
      consecutive_wins: 0, consecutive_losses: 0,
      candidate_score: null, status: 'PAPER_TESTING',
      computed_at: nowIso, metric_version: METRIC_VERSION,
    };
  }
  const nets = trades.map(t => t.net_pnl || 0);
  const grosses = trades.map(t => t.gross_pnl || 0);
  const wins = nets.filter(x => x > 0);
  const losses = nets.filter(x => x <= 0);
  const grossWins = trades.filter(t => (t.net_pnl || 0) > 0).reduce((s, t) => s + (t.gross_pnl || 0), 0);
  const grossLossAbs = Math.abs(trades.filter(t => (t.net_pnl || 0) <= 0).reduce((s, t) => s + (t.gross_pnl || 0), 0));
  const netPnl = nets.reduce((s, x) => s + x, 0);
  const grossPnl = grosses.reduce((s, x) => s + x, 0);
  const pf = grossLossAbs > 0 ? grossWins / grossLossAbs : (grossWins > 0 ? 999999 : 0);
  const expectancy = netPnl / n;
  const avgWin = wins.length ? wins.reduce((s, x) => s + x, 0) / wins.length : 0;
  const avgLoss = losses.length ? losses.reduce((s, x) => s + x, 0) / losses.length : 0;
  // equity curve max DD
  let eq = acct.initial_capital || 1000;
  let peak = eq, maxDD = 0;
  for (const t of trades) {
    eq += t.net_pnl || 0;
    if (eq > peak) peak = eq;
    const dd = peak > 0 ? (peak - eq) / peak : 0;
    if (dd > maxDD) maxDD = dd;
  }
  // Sharpe / Sortino (raw per-trade ratios, not annualized)
  const mean = expectancy;
  const variance = nets.reduce((s, x) => s + (x - mean) * (x - mean), 0) / n;
  const std = Math.sqrt(variance);
  const sharpe = std > 0 ? mean / std : 0;
  const downside = nets.filter(x => x < 0);
  const dVariance = downside.length ? downside.reduce((s, x) => s + x * x, 0) / n : 0;
  const dStd = Math.sqrt(dVariance);
  const sortino = dStd > 0 ? mean / dStd : 0;
  // holding time
  const holdingMins = trades.map(t => (Date.parse(t.exit_time) - Date.parse(t.entry_time)) / 60000).filter(x => isFinite(x) && x >= 0);
  const avgHolding = holdingMins.length ? holdingMins.reduce((s, x) => s + x, 0) / holdingMins.length : 0;
  // costs
  const fees = trades.reduce((s, t) => s + (t.trading_cost || 0), 0);
  const slip = trades.reduce((s, t) => s + (t.entry_slippage || 0) + (t.exit_slippage || 0), 0);
  const funding = 0; // funding recorded as FUNDING_DATA_UNAVAILABLE — numeric 0, noted
  // consecutive wins/losses (current streak at tail)
  let cWins = 0, cLosses = 0;
  for (let k = trades.length - 1; k >= 0; k--) {
    const v = trades[k].net_pnl || 0;
    if (v > 0) { if (cLosses > 0) break; cWins++; }
    else { if (cWins > 0) break; cLosses++; }
  }
  const turnover = trades.reduce((s, t) => s + (t.notional || 0), 0);
  return {
    ledger_id: acct.account_id, agent_type: acct.agent_type, agent_ref: acct.agent_ref,
    trades: n, wins: wins.length, losses: losses.length,
    win_rate: wins.length / n,
    gross_pnl: Math.round(grossPnl * 100) / 100,
    net_pnl: Math.round(netPnl * 100) / 100,
    roi: (acct.initial_capital || 1000) > 0 ? netPnl / (acct.initial_capital || 1000) : 0,
    profit_factor: Math.round(pf * 10000) / 10000,
    expectancy: Math.round(expectancy * 100) / 100,
    avg_win: Math.round(avgWin * 100) / 100,
    avg_loss: Math.round(avgLoss * 100) / 100,
    max_drawdown: Math.round(maxDD * 10000) / 10000,
    sharpe: Math.round(sharpe * 10000) / 10000,
    sortino: Math.round(sortino * 10000) / 10000,
    avg_holding_min: Math.round(avgHolding * 10) / 10,
    turnover: Math.round(turnover * 100) / 100,
    total_fees: Math.round(fees * 100) / 100,
    total_slippage: Math.round(slip * 100) / 100,
    total_funding: funding,
    consecutive_wins: cWins, consecutive_losses: cLosses,
    candidate_score: null, status: 'PAPER_TESTING',
    computed_at: nowIso, metric_version: METRIC_VERSION,
  };
}

const ledgers = accounts.map(a => metricsFor(a, positions.filter(p => p.account_id === a.account_id)));

// ── CANDIDATE-V1 scoring within each agent_type scope ──
function norm(values, v) {
  const min = Math.min.apply(null, values), max = Math.max.apply(null, values);
  if (values.length <= 1 || max === min) return 0.5;
  return (v - min) / (max - min);
}
const scopes = [...new Set(ledgers.map(l => l.agent_type))];
for (const scope of scopes) {
  const group = ledgers.filter(l => l.agent_type === scope);
  const netVals = group.map(l => l.net_pnl);
  const pfVals = group.map(l => Math.min(l.profit_factor, 5));
  const expVals = group.map(l => l.expectancy);
  const ddVals = group.map(l => l.max_drawdown);
  for (const l of group) {
    if (l.trades === 0) { l.candidate_score = null; l.status = 'PAPER_TESTING'; continue; }
    // stability: fraction of up to 3 equal time buckets with net_pnl > 0
    const trades = positions.filter(p => p.account_id === l.ledger_id).sort((a, b) => Date.parse(a.exit_time) - Date.parse(b.exit_time));
    let stability = null;
    if (trades.length >= 3) {
      const third = Math.floor(trades.length / 3);
      const buckets = [trades.slice(0, third), trades.slice(third, 2 * third), trades.slice(2 * third)];
      const posBuckets = buckets.filter(b => b.reduce((s, t) => s + (t.net_pnl || 0), 0) > 0).length;
      stability = posBuckets / 3;
    }
    const stabPart = stability === null ? 0 : 0.10 * stability;
    const netWeight = stability === null ? 0.35 : 0.25;
    l.candidate_score = Math.round((
      netWeight * norm(netVals, l.net_pnl)
      + 0.20 * norm(pfVals, Math.min(l.profit_factor, 5))
      + 0.20 * norm(expVals, l.expectancy)
      + 0.15 * (1 - norm(ddVals, l.max_drawdown))
      + 0.10 * Math.min(l.trades, 30) / 30
      + stabPart
    ) * 10000) / 10000;
  }
  // status transitions per scope
  const scored = group.filter(l => l.candidate_score !== null).sort((a, b) => b.candidate_score - a.candidate_score);
  const topDecileIdx = Math.max(0, Math.ceil(scored.length * 0.1) - 1);
  const topDecileCut = scored.length ? scored[topDecileIdx].candidate_score : Infinity;
  for (const l of group) {
    if (l.trades >= 10 && l.candidate_score >= topDecileCut && l.max_drawdown < 0.30) l.status = 'CANDIDATE';
    else if (l.trades >= 10 && l.net_pnl > 0) l.status = 'PROMISING';
    else l.status = 'PAPER_TESTING';
  }
}

// ── Deterministic leaderboard ──
const board = [];
const ranked = ledgers.filter(l => l.candidate_score !== null)
  .sort((a, b) => b.candidate_score - a.candidate_score || (a.agent_ref < b.agent_ref ? -1 : 1));
ranked.forEach((l, idx) => {
  board.push({
    leaderboard_id: 'LB-' + l.agent_type + '-' + (idx + 1),
    scope: l.agent_type === 'PATTERN' ? 'PATTERN' : l.agent_type === 'ENSEMBLE' ? 'ENSEMBLE' : 'AGENT',
    rank: idx + 1,
    ref: l.agent_ref,
    key_metric: 'candidate_score',
    value: l.candidate_score,
    status: l.status,
    computed_at: nowIso,
  });
});

return [{ json: {
