// ---- Data Quality Layer (dedup, sort, missing-candle detection, invalid values) ----
const seen = new Set();
const clean = [];
let invalid = 0, duplicates = 0;
for (const c of all) {
  if (!isFinite(c.open) || !isFinite(c.high) || !isFinite(c.low) || !isFinite(c.close) || !isFinite(c.volume)) { invalid++; continue; }
  if (c.high < c.low) { invalid++; continue; }
  if (seen.has(c.open_time)) { duplicates++; continue; }
  seen.add(c.open_time);
  clean.push(c);
}
clean.sort((a, b) => a.open_time < b.open_time ? -1 : 1);

const intervalMinutes = { '1m': 1, '5m': 5, '15m': 15, '30m': 30, '1h': 60 }[meta.interval] || 15;
const expectedMs = intervalMinutes * 60000;
let missing = 0;
for (let i = 1; i < clean.length; i++) {
  const gap = new Date(clean[i].open_time).getTime() - new Date(clean[i-1].open_time).getTime();
  if (gap > expectedMs) missing += Math.round(gap / expectedMs) - 1;
}
// trim to requested limit (keep the most recent candles)
const trimmed = clean.length > meta.limit ? clean.slice(clean.length - meta.limit) : clean;
const quality_status = (trimmed.length === 0) ? 'empty' : (missing > 0 ? 'gaps' : (invalid + duplicates > 0 ? 'cleaned' : 'ok'));

