const SYMBOLS = ['BTCUSDT','ETHUSDT','BNBUSDT','SOLUSDT','DOGEUSDT','XRPUSDT','ADAUSDT','LTCUSDT','LINKUSDT','AVAXUSDT','NEARUSDT'];
const WINDOWS = [
  { window: '1H', interval: '1h', limit: 168 },
  { window: '24H', interval: '1h', limit: 168 },
];
const out = [];
for (const s of SYMBOLS) for (const w of WINDOWS) out.push({ json: { symbol: s, ...w } });
return out;

const now = Date.now();
const nowIso = new Date().toISOString();
const items = $('Collect Batch Results').all().map(i => i.json);

function atr(candles, period) {
  if (candles.length < period + 1) return null;
  let sum = 0;
  for (let i = candles.length - period; i < candles.length; i++) {
    const h = candles[i].high, l = candles[i].low, pc = candles[i - 1].close;
    sum += Math.max(h - l, Math.abs(h - pc), Math.abs(l - pc));
  }
  return sum / period;
}

const out = [];
for (const it of items) {
  const symbol = it.symbol;
  const windowName = it.window;
  const need = 50;
  const dataTimestamp = it.raw.length ? new Date(it.raw[it.raw.length - 1][6]).toISOString() : nowIso;

  const base = {
    hunt_key: symbol + '_' + windowName,
    asset: symbol, window: windowName,
    data_timestamp: dataTimestamp,
    score_version: 'HUNT-V1',
    created_at: nowIso,
  };

  if (it.error || !Array.isArray(it.raw) || it.raw.length < need) {
    out.push({ json: { ...base,
      hunt_score: null, regime: 'DATA_ERROR',
      volatility: null, atr: null, range_pct: null, move_pct: null,
      volume: null, volume_anomaly: null, trend_strength: null,
      liquidity_proxy: null, spread_proxy: null, direction: null,
      max_excursion: null, drawdown: null,
    } });
    continue;
  }

  const closed = it.raw
    .map(k => ({ open: parseFloat(k[1]), high: parseFloat(k[2]), low: parseFloat(k[3]), close: parseFloat(k[4]), volume: parseFloat(k[5]), close_time: k[6] }))
    .filter(c => c.close_time < now && isFinite(c.close));

  if (closed.length < need) {
    out.push({ json: { ...base,
      hunt_score: null, regime: 'DATA_ERROR',
      volatility: null, atr: null, range_pct: null, move_pct: null,
      volume: null, volume_anomaly: null, trend_strength: null,
      liquidity_proxy: null, spread_proxy: null, direction: null,
      max_excursion: null, drawdown: null,
    } });
    continue;
  }

  const atr14 = atr(closed, 14);
  const last = closed[closed.length - 1];
  const atrPct = last.close > 0 ? atr14 / last.close : 0;

  const windowBars = windowName === '1H' ? 24 : 24;
  const ref = closed[Math.max(0, closed.length - 1 - windowBars)];
  const move = (last.close - ref.close) / ref.close;

  const lookback = Math.min(24, closed.length);
  let volSum = 0, hiMax = 0, loMin = Infinity, peak = closed[closed.length - lookback].close, maxDD = 0, maxEx = 0;
  for (let i = closed.length - lookback; i < closed.length; i++) {
    volSum += closed[i].volume;
    if (closed[i].high > hiMax) hiMax = closed[i].high;
    if (closed[i].low < loMin) loMin = closed[i].low;
    if (closed[i].close > peak) peak = closed[i].close;
    const dd = peak > 0 ? (peak - closed[i].close) / peak : 0;
    if (dd > maxDD) maxDD = dd;
    const ex = ref.close > 0 ? Math.abs(closed[i].high - ref.close) / ref.close : 0;
    if (ex > maxEx) maxEx = ex;
  }
  const avgVol = volSum / lookback;
  const volAnomaly = avgVol > 0 ? last.volume / avgVol : 1;
  const rangePct = ref.close > 0 ? (hiMax - loMin) / ref.close : 0;
  const direction = move > 0.002 ? 'UP' : (move < -0.002 ? 'DOWN' : 'FLAT');
  const trendStrength = Math.abs(move) / Math.max(rangePct, 1e-9);
  const liqProxy = avgVol * last.close / 100000;

  const volScore = Math.min(1, atrPct / 0.03);
  const trendScore = Math.min(1, trendStrength);
  const liqScore = Math.min(1, volAnomaly / 2);
  const moveScore = Math.min(1, Math.abs(move) / 0.05);
  const huntScore = Math.round((volScore * 0.3 + trendScore * 0.25 + liqScore * 0.2 + moveScore * 0.25) * 100);

  let regime;
  if (Math.abs(move) > 0.01) regime = move > 0 ? 'trending_up' : 'trending_down';
  else regime = atrPct > 0.005 ? 'volatile_ranging' : 'ranging';

  out.push({ json: { ...base,
