const KEEP = ['pattern_id','cycle_id','status','validation_version','research_version','oos_sample_size','p_value','bh_rejected','wf_results','evidence_score','sample_size','win_rate','net_return','market','timeframe'];
// Keep one row per (cycle_id, pattern_id) — the latest update wins.
