const crypto = require('crypto');
const benchmarkFilter = ($('Parse Input').first().json.benchmark_id || '').trim();

// Rows are read from their source nodes directly (not via $input) so this
// node is immune to upstream alwaysOutputData placeholders ({} items).
const queueRows = $('Read Task Queue').all().map(i => i.json);
