const patternRows = $('Slim Pattern Fields').all().map(i => i.json);
const archiveRows = $('Read Report Archive').all().map(i => i.json).filter(r => r && r.task_id);

const REPORTABLE = ['COMPLETED', 'FAILED', 'FAILED_RETRY_EXHAUSTED'];
const filteredQueue = queueRows.filter(q => q.benchmark_id === benchmarkFilter);

function sha256(str) {
  return crypto.createHash('sha256').update(String(str), 'utf8').digest('hex');
}

// Stable normalized JSON: sorted keys, archive_id/timestamps excluded
function stableStringify(obj) {
  const keys = Object.keys(obj).sort();
  const parts = keys.map(k => JSON.stringify(k) + ':' + JSON.stringify(obj[k]));
  return '{' + parts.join(',') + '}';
}

const now = new Date().toISOString();
const reports = [];

for (const q of filteredQueue) {
  const task_id = q.task_id || '';
  const worker_id = q.worker_id || '';
  const execution_id = q.execution_id || '';
  const status = q.status || '';

  if (!REPORTABLE.includes(status)) continue;

  const taskAttempts = attemptRows.filter(a => a.task_id === task_id);
  const taskPatterns = patternRows.filter(p => p.cycle_id === task_id);
  const patternIds = taskPatterns.map(p => p.pattern_id).filter(Boolean);
  const uniquePatternIds = new Set(patternIds);

  const candles = (q.candles_fetched == null ? null : Number(q.candles_fetched));
  const validationVersion = (taskPatterns.find(p => p.validation_version) || {}).validation_version || '';
  const researchVersion = (taskPatterns.find(p => p.research_version) || {}).research_version || '';

  const started = q.started_at ? new Date(q.started_at).getTime() : null;
  const finished = q.finished_at ? new Date(q.finished_at).getTime() : null;
  const runtime_ms = (started != null && finished != null && finished >= started) ? (finished - started) : null;

  const errorsJoined = [q.last_error, ...taskAttempts.map(a => a.error).filter(Boolean)].filter(Boolean).join(' | ');

  const report = {
    research_id: q.batch_id || q.benchmark_id || '',
    task_id,
    worker_id,
    execution_id,
    symbol: q.symbol || '',
    timeframe: q.timeframe || '',
    dataset_version: researchVersion,
    validation_version: validationVersion,
    candles_count: candles,
    data_quality: (candles != null && candles >= 100) ? 'ok' : 'low',
    hypotheses_tested: taskPatterns.length,
    patterns_discovered: (q.patterns_discovered != null ? Number(q.patterns_discovered) : taskPatterns.length),
    patterns_rejected: taskPatterns.filter(p => p.status === 'REJECTED').length,
    patterns_oos: taskPatterns.filter(p => (p.oos_sample_size != null && Number(p.oos_sample_size) > 0)).length,
    fdr_pass: taskPatterns.filter(p => p.bh_rejected === false && p.p_value != null).length,
    wf_pass: taskPatterns.filter(p => p.wf_results != null && String(p.wf_results).trim() !== '').length,
    validated_patterns: taskPatterns.filter(p => p.status === 'VALIDATED').length,
    evidence_score: taskPatterns.reduce((m, p) => Math.max(m, (p.evidence_score != null ? Number(p.evidence_score) : 0)), 0),
    errors: errorsJoined,
    runtime_ms,
    task_status: status,
    attempt: (q.attempt != null ? Number(q.attempt) : null),
  };

  // Real SHA-256 over stable normalized JSON (no archive_id, no timestamps)
  report.report_hash = sha256(stableStringify(report));

  // Idempotency: a report is duplicate only if the ARCHIVE already contains
  // this exact report_hash for this task_id (hash itself is content-stable).
  const alreadyArchived = archiveRows.some(a => a.task_id === task_id && a.report_hash === report.report_hash);

  const dedupKey = execution_id ? (execution_id + '|' + task_id) : (report.research_id + '|' + task_id + '|' + worker_id + '|' + report.report_hash);

  const qaFails = [];
  if (!worker_id) qaFails.push('missing worker_id');  if (candles == null || candles < 0) qaFails.push('invalid candles_count');
  if (status === 'COMPLETED' && (candles == null || candles <= 0)) qaFails.push('COMPLETED task with no candles');
  if (status === 'COMPLETED' && !validationVersion) qaFails.push('missing validation_version');
  if (patternIds.length !== uniquePatternIds.size) qaFails.push('duplicate pattern_id within task');
  if (!task_id) qaFails.push('missing task_id');
  // Duplicate detection is separate from QA — never a QA_REJECTED reason
  const qaStatus = qaFails.length ? 'QA_REJECTED' : 'ARCHIVED';
  const isDuplicate = alreadyArchived;

  reports.push({
    archive_id: 'ARCH-' + task_id + '-' + (execution_id || 'noexec'),
    research_id: report.research_id,
    task_id,
    worker_id,
    execution_id,
    symbol: report.symbol,
    timeframe: report.timeframe,
    dataset_version: report.dataset_version,
    validation_version: report.validation_version,
    candles_count: report.candles_count,
    data_quality: report.data_quality,
    hypotheses_tested: report.hypotheses_tested,
    patterns_discovered: report.patterns_discovered,
    patterns_rejected: report.patterns_rejected,
    patterns_oos: report.patterns_oos,
    fdr_pass: report.fdr_pass,
    wf_pass: report.wf_pass,
    validated_patterns: report.validated_patterns,
    evidence_score: report.evidence_score,
    errors: report.errors,
    runtime_ms: report.runtime_ms,
    task_status: status,
    attempt: report.attempt,
    report_hash: report.report_hash,
    dedup_key: dedupKey,
    status: qaStatus,
    qa_notes: qaFails.join('; '),
    is_duplicate: isDuplicate,
    archived_at: now,
    payload_json: JSON.stringify(report),
  });
}

if (reports.length === 0) return [{ json: { no_reports: true, is_duplicate: true } }];
return reports.map(r => ({ json: r }));

const benchmarkFilter = ($('Parse Input').first().json.benchmark_id || '').trim();
const queueRows = $('Read Task Queue').all().map(i => i.json).filter(q => q.benchmark_id === benchmarkFilter);
const attemptRows = $('Read Attempt Log').all().map(i => i.json);
const reports = $('Normalize + QA Reports').all().map(i => i.json).filter(r => r && r.task_id);
const archiveBefore = $('Read Report Archive').all().map(i => i.json).filter(r => r && r.task_id);
let insertedRows = [];
try {
  // Node may not have executed at all when zero fresh reports exist (branch died)
  insertedRows = $('Insert Into Report Archive').all().map(i => i.json).filter(r => r && r.task_id);
} catch (e) {
  insertedRows = [];
}

const statusCount = (s) => queueRows.filter(q => q.status === s).length;
// workers_active: actual execution evidence — distinct workers that logged attempts for this batch's tasks
const batchTaskIds = new Set(queueRows.map(q => q.task_id));
const workersActive = new Set(attemptRows.filter(a => batchTaskIds.has(a.task_id)).map(a => a.worker_id).filter(Boolean)).size;

const fresh = reports.filter(r => !r.is_duplicate);
const dupes = reports.filter(r => r.is_duplicate);
const archived = fresh.filter(r => r.status === 'ARCHIVED');
const qaRejected = fresh.filter(r => r.status === 'QA_REJECTED');

const archivedTaskIds = new Set([...archiveBefore.map(a => a.task_id), ...insertedRows.map(a => a.task_id)]);
const lostTasks = queueRows.filter(q => ['COMPLETED','FAILED','FAILED_RETRY_EXHAUSTED'].includes(q.status) && !archivedTaskIds.has(q.task_id)).length;

const apiErrors = attemptRows.filter(a => a.error && String(a.error).trim()).length;
const sum = (arr, k) => arr.reduce((s, r) => s + (Number(r[k]) || 0), 0);

const report = {
  benchmark_filter: benchmarkFilter || '(all)',
  new_inserts: insertedRows.length,
  duplicate_archive: dupes.length,
  generated_at: new Date().toISOString(),
  total_tasks: queueRows.length,
  workers_active: workersActive,
  completed: statusCount('COMPLETED'),
  failed: statusCount('FAILED'),
  exhausted: statusCount('FAILED_RETRY_EXHAUSTED'),
  running: statusCount('RUNNING'),
  pending: statusCount('PENDING'),
  stuck_running: statusCount('RUNNING'),
  duplicates: dupes.length,
  lost_tasks: lostTasks,
  api_errors: apiErrors,
  crashes: 0,
  reports_collected: reports.length,
  archived_reports: archived.length,
  qa_rejected: qaRejected.length,
  patterns_discovered: sum(fresh, 'patterns_discovered'),
  oos_patterns: sum(fresh, 'patterns_oos'),
  fdr_pass: sum(fresh, 'fdr_pass'),
  wf_pass: sum(fresh, 'wf_pass'),
  validated: sum(fresh, 'validated_patterns'),
};

if (report.lost_tasks > 0 || report.stuck_running > 0) {
  report.verdict = 'BLOCKED';
} else if (report.qa_rejected > 0 || report.failed > 0) {
  report.verdict = 'PASS_WITH_WARNINGS';
} else {
  report.verdict = 'PASS';
}

return [{ json: report }];
